import os

from fastapi import FastAPI, HTTPException
from fastapi.responses import PlainTextResponse

app = FastAPI()
EXPORT_DIR = "/srv/exports"


@app.get("/exports", response_class=PlainTextResponse)
def read_export(name: str):
    candidate = os.path.realpath(os.path.join(EXPORT_DIR, name))
    if not candidate.startswith(EXPORT_DIR + os.sep):
        raise HTTPException(status_code=404)
    with open(candidate, encoding="utf-8") as handle:
        return handle.read()

import requests
from flask import Flask, abort, request

app = Flask(__name__)
FEEDS = {
    "status": "https://status.example.com/feed.json",
    "changelog": "https://example.com/changelog.json",
}


@app.get("/preview")
def preview():
    feed = FEEDS.get(request.args.get("feed", ""))
    if feed is None:
        abort(404)
    response = requests.get(feed, timeout=5)
    return response.text[:500]

