import sqlite3

from fastapi import FastAPI

app = FastAPI()


def orders_for(customer: str) -> list:
    connection = sqlite3.connect("orders.db")
    query = "SELECT id, total FROM orders WHERE customer = '{}'".format(customer)
    return connection.execute(query).fetchall()


@app.get("/orders")
def list_orders(customer: str):
    return {"orders": orders_for(customer)}

