const express = require('express');
const { execSync } = require('child_process');

const app = express();

function renderReport(name) {
  return execSync('report-tool --render ' + name).toString();
}

app.get('/reports', (req, res) => {
  res.type('text/plain').send(renderReport(req.query.name));
});

const express = require('express');
const { execFileSync } = require('child_process');

const app = express();

function renderReport(name) {
  return execFileSync('report-tool', ['--render', String(name)]).toString();
}

app.get('/reports', (req, res) => {
  res.type('text/plain').send(renderReport(req.query.name));
});
